data.modelserve_drain.py:
"""Graceful drain for a vLLM slot, loaded into the engine with `vllm serve --middleware modelserve_drain.DrainMiddleware`
(the controller mounts this file as modelserve_drain.py and puts it on PYTHONPATH).

The controller POSTs /modelserve/drain once the slot is out of the Service. From then on every response carries
`Connection: close`, so a keep-alive client finishes its request and reconnects (to the new slot) on its own, instead of
finding its pooled connection cut when the pod is deleted. Idle connections go on uvicorn's keep-alive timeout (5 s).
"""

DRAIN_PATH = "/modelserve/drain"


class DrainMiddleware:
    draining = False

    def __init__(self, app):
        self.app = app

    async def __call__(self, scope, receive, send):
        if scope["type"] != "http":
            return await self.app(scope, receive, send)
        if scope["path"] == DRAIN_PATH and scope["method"] == "POST":
            DrainMiddleware.draining = True
            await send({"type": "http.response.start", "status": 200,
                        "headers": [(b"content-type", b"text/plain"), (b"connection", b"close")]})
            await send({"type": "http.response.body", "body": b"draining\n"})
            return
        if not DrainMiddleware.draining:
            return await self.app(scope, receive, send)

        async def send_close(message):
            if message["type"] == "http.response.start":
                headers = [(k, v) for k, v in message.get("headers") or [] if k.lower() != b"connection"]
                message = {**message, "headers": [*headers, (b"connection", b"close")]}
            await send(message)

        return await self.app(scope, receive, send_close)
